{
  "findings": [
    {
      "ref": "[D526]",
      "area": "contact",
      "claim": "A parent reports that strangers can chat with your child in the same room or location.",
      "stance": "risk",
      "quote": "Users interact with anyone else playing the game at the same time. They can add friends and then send private messages or openly chat with anyone in the same room or location in the game."
    },
    {
      "ref": "[D526]",
      "area": "contact",
      "claim": "A parent reports that private messaging with strangers is possible.",
      "stance": "risk",
      "quote": "They can add friends and then send private messages or openly chat with anyone in the same room or location in the game."
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "A parent reports that in-app purchases are required to access full clothing, furniture, and destinations.",
      "stance": "risk",
      "quote": "Playable without in-app purchases, but access to full array of clothes, furniture, and destinations requires it."
    },
    {
      "ref": "[D526]",
      "area": "data",
      "claim": "A parent reports that personal information shared in chat or private messages can be captured, stored, and used.",
      "stance": "risk",
      "quote": "This game puts most of the responsibility on users and parents when it comes to staying protected in the game. Users can block others or create a \"grief report\" if they feel like another user is harassing them and are given different methods of staying safe on the game, but younger players may not follow these guidelines or even be aware of them. Like many similar games, there's not much in the way of active moderation within the game, so parents are asked to set parental controls on their devices if allowing their kids to play in this digital space."
    },
    {
      "ref": "[D526]",
      "area": "data",
      "claim": "A parent reports that the privacy policy states users must be at least 13 and that personal data can be captured.",
      "stance": "risk",
      "quote": "The [privacy policy](http://www.avakin.com/terms-of-service/#PP) reiterates that users must be at least 13 and specifies that any personal information shared in the game, including birth date and location, even through chat and private message, can be captured, stored, and used."
    },
    {
      "ref": "[D526]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate can be easily faked by savvy kids.",
      "stance": "risk",
      "quote": "When setting up an account it checks to verify age requirements, but it's pretty easy for a savvy kid to fake their birthdate to gain access."
    },
    {
      "ref": "[D526]",
      "area": "content",
      "claim": "A parent reports that chat is rife with suggestive comments and creative profanity.",
      "stance": "risk",
      "quote": "Chat is full of suggestive comments and creative profanity, since swearing is blocked by the game."
    },
    {
      "ref": "[D526]",
      "area": "content",
      "claim": "A parent reports that avatars can be dressed in underwear or bikinis and that flirting occurs in chat.",
      "stance": "risk",
      "quote": "Avatars can be dressed in underwear or bikinis but don't do anything suggestive or sexual; however, chat feature is rife with flirting and suggestive comments."
    }
  ]
}
